477	    fn get_or_insert_with<'a>(
478	        &self,
479	        key: &crate::AtlasKey,
480	        build: &mut dyn FnMut() -> anyhow::Result<
481	            Option<(Size<crate::DevicePixels>, std::borrow::Cow<'a, [u8]>)>,
482	        >,
483	    ) -> anyhow::Result<Option<crate::AtlasTile>> {
484	        let mut state = self.0.lock();
485	        if let Some(&tile) = state.tiles.get(key) {
486	            return Ok(Some(tile));
487	        }
488	        drop(state);
489	
490	        let Some((size, _)) = build()? else {
491	            return Ok(None);
492	        };
493	
494	        let mut state = self.0.lock();
495	        state.next_id += 1;
496	        let texture_id = state.next_id;
497	        state.next_id += 1;
498	        let tile_id = state.next_id;
499	
500	        state.tiles.insert(
501	            key.clone(),
502	            crate::AtlasTile {
503	                texture_id: AtlasTextureId {
504	                    index: texture_id,
505	                    kind: crate::AtlasTextureKind::Monochrome,
506	                },
507	                tile_id: TileId(tile_id),
508	                padding: 0,
509	                bounds: crate::Bounds {
510	                    origin: Point::default(),
511	                    size,
512	                },
513	            },
514	        );
515	
516	        Ok(Some(state.tiles[key]))
517	    }
