168	        &self,
169	        select_paths: impl FnOnce(&PathPromptOptions) -> Option<Vec<std::path::PathBuf>>,
170	    ) {
171	        let (options, tx) = self
172	            .prompts
173	            .borrow_mut()
174	            .paths
175	            .pop_front()
176	            .expect("no pending paths prompt");
177	        let selection = select_paths(&options);
178	        if let Some(paths) = &selection
179	            && !options.multiple
180	            && paths.len() > 1
181	        {
182	            panic!(
183	                "selected {} paths for a prompt that does not allow multiple selection",
184	                paths.len()
185	            );
186	        }
187	        tx.send(Ok(selection)).ok();
188	    }
