199	            .multiple_choice
200	            .pop_front()
201	            .expect("no pending multiple choice prompt");
202	        let Some(ix) = prompt.answers.iter().position(|a| a == response) else {
203	            panic!(
204	                "PROMPT: {}\n{:?}\n{:?}\nCannot respond with {}",
205	                prompt.msg, prompt.detail, prompt.answers, response
206	            )
207	        };
208	        prompt.tx.send(ix).ok();
209	    }
