248	    pub(crate) fn set_active_window(&self, window: Option<TestWindow>) {
249	        let executor = self.foreground_executor();
250	        let previous_window = self.active_window.borrow_mut().take();
251	        self.active_window.borrow_mut().clone_from(&window);
252	
253	        executor
254	            .spawn(async move {
255	                if let Some(previous_window) = previous_window {
256	                    if let Some(window) = window.as_ref()
257	                        && Rc::ptr_eq(&previous_window.0, &window.0)
258	                    {
259	                        return;
260	                    }
261	                    previous_window.simulate_active_status_change(false);
262	                }
263	                if let Some(window) = window {
264	                    window.simulate_active_status_change(true);
265	                }
266	            })
267	            .detach();
268	    }
