293	    ) {
294	        let callback = self
295	            .system_notifications
296	            .borrow_mut()
297	            .response_callback
298	            .take();
299	        if let Some(mut callback) = callback {
300	            callback(response);
301	            self.system_notifications
302	                .borrow_mut()
303	                .response_callback
304	                .get_or_insert(callback);
305	        }
306	    }
